<?php/** * Description of Comments * * @author Suharshana DsW */class File {    public $id;    public $creator;    public $name;    public $number;    public $type;    public $note;     public $uploaded_on;    public $queue;    public function __construct($id) {        if ($id) {            $query = "SELECT * FROM `file` WHERE `id`=" . $id;            $db = new Database();            $result = mysqli_fetch_array($db->readQuery($query));            $this->id = $result['id'];            $this->creator = $result['creator'];            $this->name = $result['name'];            $this->number = $result['number'];            $this->type = $result['type'];            $this->note = $result['note'];             $this->uploaded_on = $result['uploaded_on'];            $this->queue = $result['queue'];            return $this;        }    }    public function create() {        $query = "INSERT INTO `file` (`creator`,`name`,`number`,`type`,`note`,`uploaded_on`,`queue`) VALUES  ('"                . $this->creator . "','"                . $this->name . "','"                . $this->number . "','"                . $this->type . "','"                . $this->note . "',"                . "now(),'"                . $this->queue . "')";               $db = new Database();        $result = $db->readQuery1($query);        if ($result) {            return $result;        } else {            return FALSE;        }    }    public function all() {        $query = "SELECT * FROM `file` ORDER BY uploaded_on DESC";        $db = new Database();        $result = $db->readQuery($query);        $array_res = array();        while ($row = mysqli_fetch_array($result)) {            array_push($array_res, $row);        }        return $array_res;    }    public function CreatorFiles($creator) {        $query = "SELECT * FROM `file` WHERE `creator` = '" . $creator . "' ORDER BY uploaded_on DESC";        $db = new Database();        $result = $db->readQuery($query);        $array_res = array();        while ($row = mysqli_fetch_array($result)) {            array_push($array_res, $row);        }        return $array_res;    }    public function update() {        $query = "UPDATE  `file` SET "                . "`queue` ='" . $this->queue . "',"                . "`note` ='" . $this->note . "'"                . "WHERE `id` = '" . $this->id . "'";        var_dump($query);                $db = new Database();        $result = $db->readQuery($query);        if ($result) {            return $this->__construct($this->id);        } else {            return FALSE;        }    }    public function delete() {        $query = 'DELETE FROM `file` WHERE id="' . $this->id . '"';        $db = new Database();        return $db->readQuery($query);    }    public function arrange($key, $img) {        $query = "UPDATE `file` SET `queue` = '" . $key . "'  WHERE id = '" . $img . "'";        $db = new Database();        $result = $db->readQuery($query);        return $result;    }}